    if(mode==='remove'&&state.workflow!=='class')reasons.push('Removing assignment defaults is available only in Assignment dates');if(assignments.some((assignment)=>assignment.published===false))warnings.push(`${assignments.filter((assignment)=>assignment.published===false).length} selected assignment(s) are unpublished`);const addingToUndated=assignments.filter((assignment)=>!assignment.due_at&&mode!=='remove'&&mode!=='shift'),unmatchedNew=addingToUndated.filter((assignment)=>!gsMatch(assignment));if(unmatchedNew.length)warnings.push(`${unmatchedNew.length} undated assignment(s) will receive a Canvas date but have no Gradescope match`);
    const matched=assignments.filter((assignment)=>gsMatch(assignment)).length,method=repair?'Repair Gradescope from existing Canvas extensions':mode==='shift'?`Shift dates ${document.getElementById('cgde-days').value||'?'} day(s)${document.getElementById('cgde-shift-late').value==='none'?' and remove late windows':' and shift existing late windows'}`:mode==='same'?`Use ${document.getElementById('cgde-same-due').value||'one shared date'}${document.getElementById('cgde-same-late-mode').value==='none'?' with no late window':' with a separate late cutoff'}`:mode==='remove'?'Remove class due and late dates':'Use the individual dates shown below';
