  function formatClock(value){if(!validTime(value))return '11:59 PM';const [hours,minutes]=value.split(':').map(Number),suffix=hours>=12?'PM':'AM';return `${hours%12||12}:${String(minutes).padStart(2,'0')} ${suffix}`;}
  function saveDefaultTimes(){const due=document.getElementById('cgde-due-time').value,late=document.getElementById('cgde-late-time').value;if(!validTime(due)||!validTime(late)){showError(new Error('Choose valid default due and late times.'));return;}GM_setValue(TIME_SETTINGS_KEY,{due,late});document.getElementById('cgde-due-time-label').textContent=formatClock(due);document.getElementById('cgde-late-time-label').textContent=formatClock(late);invalidate();setStatus(`Default times saved: due ${formatClock(due)}, late ${formatClock(late)}.`,'cgde-ok');}
