  function renderGradescope(error=''){ const node=document.getElementById('cgde-gs'),field=document.getElementById('cgde-gs-course-field'),select=document.getElementById('cgde-gs-course'); if(error){node.className='cgde-error';node.textContent=error;document.getElementById('cgde-gs-retry').classList.remove('cgde-hidden');field.classList.add('cgde-hidden');}else if(state.gs?.course){node.className='cgde-ok';node.textContent=`Gradescope: ${state.gs.course.code} — ${state.gs.course.name}`;document.getElementById('cgde-gs-retry').classList.add('cgde-hidden');field.classList.remove('cgde-hidden');}else{node.className='cgde-warn';node.textContent=state.gs?.connected?'Choose the matching Gradescope course below. Canvas remains available.':'Gradescope unavailable; Canvas-only mode.';document.getElementById('cgde-gs-retry').classList.remove('cgde-hidden');field.classList.toggle('cgde-hidden',!state.gs?.courses?.length);} if(state.gs?.courses?.length){const current=state.gs.course?.id||'';select.innerHTML='<option value="">Choose the matching course…</option>'+state.gs.courses.map((c)=>`<option value="${c.id}"${c.id===current?' selected':''}>${escapeHtml(c.code)} — ${escapeHtml(c.name)}</option>`).join('');}state.current.clear();renderAssignmentResults();renderQueue(); }
  async function chooseGradescopeCourse(){ const id=document.getElementById('cgde-gs-course').value;if(!id)return;const course=state.gs?.courses.find((c)=>c.id===id);if(!course)return;setStatus(`Loading Gradescope course ${course.code}…`);try{state.gs=await loadGradescopeCourse(course,state.gs.courses);renderGradescope();renderQueue();updateLiveSummary();setStatus(`Gradescope course mapped; ${state.gs.assignments.length} assignments loaded.`,'cgde-ok');}catch(e){renderGradescope(e.message);updateLiveSummary();showError(e);} }
