  async function getOverride(assignmentId,studentId){ const rows=await canvasPages(`/api/v1/courses/${courseId}/assignments/${assignmentId}/overrides?per_page=100`); return rows.find((o)=>(o.student_ids||[]).map(String).includes(String(studentId)))||null; }
  function extensionRows(text){const doc=parseHtml(text);return Array.from(doc.querySelectorAll('[data-react-class="EditExtension"]')).map((node)=>readJsonAttr(node,'data-react-props').override).filter(Boolean);}
  function extensionEntries(text){const doc=parseHtml(text);return Array.from(doc.querySelectorAll('[data-react-class="EditExtension"]')).map((node)=>readJsonAttr(node,'data-react-props')).filter((entry)=>entry.override);}
  function gradescopeStudentFor(student){if(!state.gs?.students||!student?.email)return null;const hits=state.gs.students.filter((entry)=>entry.email===(student.email||'').toLowerCase());return hits.length===1?hits[0]:null;}
  async function getGradescopeExtension(assignmentId,userId){if(!assignmentId||!userId)return null;const page=await gsRequest('GET',`/courses/${state.gs.course.id}/assignments/${assignmentId}/extensions`);return extensionRows(page.responseText).find((item)=>String(item.user_id)===String(userId))||null;}
  async function autoFindRepairs(){if(selectedStudents().length!==1){showError(new Error('Select exactly one student for automatic Gradescope repair.'));return;}if(!state.gs?.course){showError(new Error('Choose and connect the matching Gradescope course first.'));return;}const email=(state.student.email||'').toLowerCase(),gsStudents=state.gs.students.filter((student)=>student.email===email);if(gsStudents.length!==1){showError(new Error('The selected student email does not uniquely match the Gradescope roster.'));return;}const candidates=state.assignments.map((assignment)=>({assignment,gs:gsMatch(assignment)})).filter((item)=>item.gs),button=document.getElementById('cgde-find-repairs');button.disabled=true;state.selectedAssignments.clear();state.current.clear();const needed=[],errors=[];try{for(let start=0;start<candidates.length;start+=5){const batch=candidates.slice(start,start+5);setStatus(`Scanning Gradescope extensions ${start+1}–${Math.min(start+batch.length,candidates.length)} of ${candidates.length}…`);const checked=await Promise.all(batch.map(async({assignment,gs})=>{try{const [override,extension]=await Promise.all([getOverride(assignment.id,state.student.id),getGradescopeExtension(gs.id,gsStudents[0].id)]);if(!override?.due_at)return null;const expectedLate=override.lock_at||override.due_at,actualDue=extension?.settings?.due_date?.value,actualLate=extension?.settings?.hard_due_date?.value;if(!extension||!closeEnough(actualDue,override.due_at)||!closeEnough(actualLate,expectedLate))return assignment;state.current.set(String(assignment.id),{canvasOverride:true,canvasDue:override.due_at,canvasLate:override.lock_at||null,gsExtension:true,gsDue:actualDue,gsLate:actualLate});return null;}catch(error){errors.push(`${assignment.name}: ${error.message}`);return null;}}));needed.push(...checked.filter(Boolean));}needed.forEach((assignment)=>state.selectedAssignments.add(String(assignment.id)));setRepairMode(true);renderQueue();renderAssignmentResults();if(needed.length)setStatus(`Found ${needed.length} missing or mismatched Gradescope extension(s). Review the queue, then Preview.`,'cgde-ok');else setStatus(errors.length?`No repairs queued; ${errors.length} assignment(s) could not be checked.`:'No Gradescope repairs are needed for this student.','cgde-ok');if(errors.length)console.warn('Gradescope repair scan errors',errors);}catch(error){showError(error);}finally{button.disabled=false;}}
  async function loadCurrentDeadlines(assignment){const key=String(assignment.id),studentId=String(state.student?.id||'');if(!studentId||state.current.has(key)||selectedStudents().length!==1)return;const gsAssignment=gsMatch(assignment),gsStudent=state.gs?.students.filter((s)=>s.email===(state.student.email||'').toLowerCase());try{const [override,extension]=await Promise.all([getOverride(assignment.id,studentId),gsAssignment&&gsStudent?.length===1?getGradescopeExtension(gsAssignment.id,gsStudent[0].id):null]);if(String(state.student?.id||'')!==studentId||selectedStudents().length!==1)return;state.current.set(key,{canvasOverride:Boolean(override),canvasDue:override?.due_at||null,canvasLate:override?.lock_at||null,gsExtension:Boolean(extension),gsDue:extension?.settings?.due_date?.value||null,gsLate:extension?.settings?.hard_due_date?.value||null});const row=document.querySelector(`#cgde-rows tr[data-id="${CSS.escape(key)}"]`);if(row){row.querySelector('.cgde-canvas-due').innerHTML=currentCell(override?.due_at,assignment.due_at,'Student override',Boolean(override));row.querySelector('.cgde-canvas-late').innerHTML=currentCell(override?.lock_at,assignment.lock_at,'Student override',Boolean(override));row.querySelector('.cgde-gs-due').innerHTML=currentCell(extension?.settings?.due_date?.value,gsAssignment?.due,'Student extension',Boolean(extension));row.querySelector('.cgde-gs-late').innerHTML=currentCell(extension?.settings?.hard_due_date?.value,gsAssignment?.late,'Student extension',Boolean(extension));row.querySelector('.cgde-new-due').value=formatDateInput(override?.due_at||assignment.due_at);row.querySelector('.cgde-new-late').value=formatDateInput(override?override.lock_at:assignment.lock_at);}}catch(error){if(selectedStudents().length!==1)return;const row=document.querySelector(`#cgde-rows tr[data-id="${CSS.escape(key)}"]`);if(row)row.querySelectorAll('.cgde-system-date').forEach((cell)=>cell.innerHTML=`<span class="cgde-error">Unavailable</span><small>${escapeHtml(error.message)}</small>`);}}

  const baseRenderQueue=renderQueue;
  renderQueue=function(){baseRenderQueue();refreshCalculatedDates();};
