  async function saveCanvas(plan){if((plan.existing?.student_ids||[]).length>1)throw new Error('Refusing to overwrite a Canvas override shared by multiple students.'); const body={assignment_override:{student_ids:[plan.student.id],title:`Extension — ${plan.student.name}`,due_at:plan.due,lock_at:plan.late}}; const path=plan.existing?`/api/v1/courses/${courseId}/assignments/${plan.assignment.id}/overrides/${plan.existing.id}`:`/api/v1/courses/${courseId}/assignments/${plan.assignment.id}/overrides`; return canvasRequest(path,{method:plan.existing?'PUT':'POST',body:JSON.stringify(body)}); }
